package com.kp.kali.core;
import org.junit.*;import org.junit.rules.TemporaryFolder;import java.io.*;import java.net.*;import java.nio.file.*;import java.security.*;import java.util.*;import static org.junit.Assert.*;
public class ManagedSetupTest {
 @Rule public TemporaryFolder temp=new TemporaryFolder();
 static String hash(byte[] b)throws Exception {byte[] h=MessageDigest.getInstance("SHA-256").digest(b);StringBuilder s=new StringBuilder();for(byte x:h)s.append(String.format("%02x",x));return s.toString();}
 static final String DIGEST="sha256:"+String.join("",Collections.nCopies(64,"a"));
 @Test public void protocolRequiresFreshReadyAfterBothRootChecks(){BootstrapProtocol p=new BootstrapProtocol(DIGEST);p.accept("KP:DESKTOP_READY:"+DIGEST);p.accept("KP:ROOT_UID:0");p.accept("KP:SUDO_UID:0");assertFalse(p.isReady());p.accept("KP:DESKTOP_READY:"+DIGEST);assertTrue(p.isReady());p.accept("KP:ERROR:broken");assertFalse(p.isReady());p.accept("KP:DESKTOP_READY:"+DIGEST);assertFalse(p.isReady());}
 @Test public void protocolRejectsMismatchAndNonRoot(){BootstrapProtocol p=new BootstrapProtocol(DIGEST);p.accept("KP:ROOT_UID:1000");p.accept("KP:SUDO_UID:0");p.accept("KP:DESKTOP_READY:"+DIGEST);assertFalse(p.isReady());assertNotNull(p.error());}
 @Test public void volumeReopensWithoutChangingDataAndMarksReady()throws Exception{ManagedVolume v=ManagedVolume.createOrOpen(temp.getRoot(),DIGEST,4096);try(RandomAccessFile r=new RandomAccessFile(v.disk,"rw")){r.write(77);}v.markReady();ManagedVolume w=ManagedVolume.createOrOpen(temp.getRoot(),DIGEST,4096);assertEquals(v.uuid,w.uuid);assertTrue(w.isReady());assertEquals(77,Files.readAllBytes(w.disk.toPath())[0]);assertThrows(IOException.class,()->ManagedVolume.createOrOpen(temp.getRoot(),DIGEST,8192));}
 @Test public void volumeRejectsUnknownAndSupportsLargeSparseFile()throws Exception{File a=temp.newFolder();Files.write(new File(a,"volume.ext4").toPath(),new byte[]{9});assertThrows(IOException.class,()->ManagedVolume.createOrOpen(a,DIGEST,512));assertEquals(9,Files.readAllBytes(new File(a,"volume.ext4").toPath())[0]);assertFalse(new File(a,"volume.properties").exists());ManagedVolume v=ManagedVolume.createOrOpen(temp.newFolder(),DIGEST,4L*1024*1024*1024);assertEquals(4L*1024*1024*1024,v.disk.length());}
 interface Reply {String respond(String request);}
 static class Server implements AutoCloseable {final ServerSocket socket;final Thread thread;volatile String request;Server(Reply reply)throws Exception{socket=new ServerSocket(0,8,InetAddress.getByName("127.0.0.1"));thread=new Thread(()->{while(!socket.isClosed())try(Socket c=socket.accept()){BufferedReader r=new BufferedReader(new InputStreamReader(c.getInputStream(),"US-ASCII"));StringBuilder q=new StringBuilder();String s;while((s=r.readLine())!=null&&!s.isEmpty())q.append(s).append('\n');request=q.toString();c.getOutputStream().write(reply.respond(request).getBytes("US-ASCII"));}catch(IOException e){}});thread.setDaemon(true);thread.start();}URL url()throws Exception{return new URL("http://127.0.0.1:"+socket.getLocalPort()+"/blob");}public void close()throws Exception{socket.close();thread.join(2000);}}
 File fetch(Server s,byte[] b,File d)throws Exception{return new VerifiedTransfer().fetch(s.url(),b.length,hash(b),d,u->Collections.emptyMap(),u->true,()->false,(n,t)->{});}
 @Test public void transferPadsAndUsesVerifiedCache()throws Exception{byte[] b="hello".getBytes("US-ASCII");File d=new File(temp.getRoot(),"blob");try(Server s=new Server(q->"HTTP/1.1 200 OK\r\nContent-Length: 5\r\n\r\nhello")){fetch(s,b,d);}assertEquals(512,d.length());assertEquals(0,Files.readAllBytes(d.toPath())[511]);try(Server s=new Server(q->{throw new AssertionError("cache requested network");})){fetch(s,b,d);}}
 @Test public void transferResumesValidatedRange()throws Exception{byte[] b="hello".getBytes("US-ASCII");File d=new File(temp.getRoot(),"blob");Files.write(new File(d+".part").toPath(),"he".getBytes("US-ASCII"));try(Server s=new Server(q->"HTTP/1.1 206 Partial Content\r\nContent-Range: bytes 2-4/5\r\nContent-Length: 3\r\n\r\nllo")){fetch(s,b,d);assertTrue(s.request.contains("Range: bytes=2-"));}assertEquals('h',Files.readAllBytes(d.toPath())[0]);}
 @Test public void transferRestartsIgnoredRange()throws Exception{byte[] b="hello".getBytes("US-ASCII");File d=new File(temp.getRoot(),"blob");Files.write(new File(d+".part").toPath(),new byte[]{99});try(Server s=new Server(q->"HTTP/1.1 200 OK\r\nContent-Length: 5\r\n\r\nhello")){fetch(s,b,d);}assertEquals('h',Files.readAllBytes(d.toPath())[0]);}
 @Test public void badBodiesPreserveExistingFinal()throws Exception{for(String body:Arrays.asList("hell","helloo","jello")){File d=new File(temp.newFolder(),"blob");Files.write(d.toPath(),new byte[]{9});try(Server s=new Server(q->"HTTP/1.1 200 OK\r\nContent-Length: "+body.length()+"\r\n\r\n"+body)){assertThrows(IOException.class,()->fetch(s,"hello".getBytes("US-ASCII"),d));}assertArrayEquals(new byte[]{9},Files.readAllBytes(d.toPath()));}}
 @Test public void cancellationDoesNotCommit()throws Exception{File d=new File(temp.getRoot(),"blob");try(Server s=new Server(q->"HTTP/1.1 200 OK\r\nContent-Length: 5\r\n\r\nhello")){assertThrows(InterruptedIOException.class,()->new VerifiedTransfer().fetch(s.url(),5,hash("hello".getBytes("US-ASCII")),d,u->Collections.emptyMap(),u->true,()->true,(n,t)->{}));}assertFalse(d.exists());}
 @Test public void redirectStripsCredentialsAndRejectsPolicy()throws Exception{File d=new File(temp.getRoot(),"blob");try(Server dest=new Server(q->"HTTP/1.1 200 OK\r\nContent-Length: 5\r\n\r\nhello");Server src=new Server(q->{try{return "HTTP/1.1 302 Found\r\nLocation: "+dest.url()+"?secret=hidden\r\nContent-Length: 0\r\n\r\n";}catch(Exception e){throw new RuntimeException(e);}})){new VerifiedTransfer().fetch(src.url(),5,hash("hello".getBytes("US-ASCII")),d,u->Collections.singletonMap("Authorization","Bearer secret"),u->true,()->false,(n,t)->{});assertFalse(dest.request.toLowerCase(Locale.ROOT).contains("authorization"));Files.delete(d.toPath());assertThrows(IOException.class,()->new VerifiedTransfer().fetch(src.url(),5,hash("hello".getBytes("US-ASCII")),d,u->Collections.emptyMap(),u->false,()->false,(n,t)->{}));}}

 @Test public void pendingReceiptRecoversMissingDiskWithoutNewIdentity()throws Exception{ManagedVolume v=ManagedVolume.createOrOpen(temp.getRoot(),DIGEST,512);Files.delete(v.disk.toPath());ManagedVolume w=ManagedVolume.createOrOpen(temp.getRoot(),DIGEST,512);assertEquals(v.uuid,w.uuid);assertFalse(w.isReady());assertEquals(512,w.disk.length());}
 @Test public void volumeRejectsSymlinksWithoutTouchingReferent()throws Exception{File other=temp.newFile();Files.write(other.toPath(),new byte[]{7});File dir=temp.newFolder();Files.createSymbolicLink(new File(dir,"volume.ext4").toPath(),other.toPath());assertThrows(IOException.class,()->ManagedVolume.createOrOpen(dir,DIGEST,512));assertArrayEquals(new byte[]{7},Files.readAllBytes(other.toPath()));}
 @Test public void fullPartCommitsWithoutNetworkAndRejectsNonzeroCachePadding()throws Exception{byte[] body="hello".getBytes("US-ASCII");File d=new File(temp.getRoot(),"blob");Files.write(new File(d+".part").toPath(),body);try(Server s=new Server(q->{throw new AssertionError("full part requested network");})){fetch(s,body,d);}try(RandomAccessFile out=new RandomAccessFile(d,"rw")){out.seek(511);out.write(1);}try(Server s=new Server(q->"HTTP/1.1 200 OK\r\nContent-Length: 5\r\n\r\nhello")){fetch(s,body,d);assertNotNull(s.request);}assertEquals(0,Files.readAllBytes(d.toPath())[511]);}
 @Test public void invalidRangeCannotPublish()throws Exception{File d=new File(temp.getRoot(),"blob");Files.write(new File(d+".part").toPath(),new byte[]{'h','e'});try(Server s=new Server(q->"HTTP/1.1 206 Partial Content\r\nContent-Range: bytes 0-2/5\r\nContent-Length: 3\r\n\r\nllo")){assertThrows(IOException.class,()->fetch(s,"hello".getBytes("US-ASCII"),d));}assertFalse(d.exists());}
 @Test public void protocolRejectsWrongDigestMalformedAndOversize(){for(String line:Arrays.asList("KP:DESKTOP_READY:sha256:"+String.join("",Collections.nCopies(64,"b")),"KP:ROOT_UID:00","KP:PHASE:"+String.join("",Collections.nCopies(1100,"x")))){BootstrapProtocol p=new BootstrapProtocol(DIGEST);p.accept("noise");p.accept("KP:ROOT_UID:0");p.accept("KP:SUDO_UID:0");p.accept(line);assertNotNull(p.error());assertFalse(p.isReady());}}
}
